import sys

def largest_brute(h):
    n = len(h)
    best = 0
    for i in range(n):
        l = i
        while l - 1 >= 0 and h[l - 1] >= h[i]:
            l -= 1
        r = i
        while r + 1 < n and h[r + 1] >= h[i]:
            r += 1
        best = max(best, h[i] * (r - l + 1))
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    h = list(map(int, data[1:1 + n]))
    print(largest_brute(h))
